import express, { Request, Response } from 'express';
import crypto from 'crypto';
import { JSDOM } from 'jsdom';

const app = express();
app.use(express.json());

const SERVICE_KEYS: Record<string, string> = {
  'monitoring-agent': 'sk_mon_a8f3e2c1d4b5',
  'log-collector': 'sk_log_7e9f1a2b3c4d',
  'dashboard-renderer': 'sk_dash_5f6a7b8c9d0e'
};

interface LogEntry {
  timestamp: number;
  service: string;
  level: string;
  message: string;
  context?: Record<string, string>;
}

interface AuthToken {
  serviceId: string;
  nonce: string;
  signature: string;
}

function verifyServiceAuth(token: AuthToken): boolean {
  const key = SERVICE_KEYS[token.serviceId];
  if (!key) return false;
  if (typeof token.signature !== 'string' || !/^[0-9a-f]+$/i.test(token.signature)) {
    return false;
  }
  const expectedSig = crypto
    .createHmac('sha256', key)
    .update(`${token.serviceId}:${token.nonce}`)
    .digest('hex');
  const expectedBuf = Buffer.from(expectedSig, 'hex');
  const providedBuf = Buffer.from(token.signature, 'hex');
  if (expectedBuf.length !== providedBuf.length) {
    return false;
  }
  return crypto.timingSafeEqual(expectedBuf, providedBuf);
}

class LogStore {
  private entries: LogEntry[] = [];

  append(entry: LogEntry): void {
    this.entries.push(entry);
  }

  query(service?: string, level?: string): LogEntry[] {
    return this.entries.filter(e =>
      (!service || e.service === service) &&
      (!level || e.level === level)
    );
  }
}

const store = new LogStore();

function sanitizeForDisplay(text: string): string {
  const entityMap: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;'
  };
  return text.replace(/[&<>"']/g, (ch) => entityMap[ch]);
}

function renderLogContext(context: Record<string, string>): string {
  const pairs = Object.entries(context).map(([k, v]) => {
    const safeKey = sanitizeForDisplay(k);
    const safeValue = sanitizeForDisplay(v);
    return `<span class="ctx-key">${safeKey}</span>=<span class="ctx-val">${safeValue}</span>`;
  });
  return pairs.join(', ');
}

function buildLogWidget(entries: LogEntry[]): string {
  const rows = entries.map(entry => {
    const time = new Date(entry.timestamp).toISOString();
    const svc = sanitizeForDisplay(entry.service);
    const lvl = sanitizeForDisplay(entry.level);
    const msg = sanitizeForDisplay(entry.message);
    const ctx = entry.context ? renderLogContext(entry.context) : '';
    return `<tr><td>${time}</td><td>${svc}</td><td class="level-${lvl}">${lvl}</td><td>${msg}</td><td>${ctx}</td></tr>`;
  });

  return `<!DOCTYPE html><html><head><title>Log Viewer</title></head><body>
<table id="logs">${rows.join('')}</table>
<script>
document.querySelectorAll('.ctx-val').forEach(el => {
  const decoded = el.textContent;
  if (decoded && decoded.startsWith('uri:')) {
    const target = decoded.substring(4);
    let safeHref = '#';
    try {
      const parsed = new URL(target, window.location.origin);
      if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
        safeHref = parsed.href;
      }
    } catch (e) {
      safeHref = '#';
    }
    const link = document.createElement('a');
    link.href = safeHref;
    link.textContent = decoded.substring(4);
    el.replaceWith(link);
  }
});
</script></body></html>`;
}

app.post('/api/v1/ingest', (req: Request, res: Response) => {
  const authHeader = req.headers['x-service-auth'];
  if (!authHeader || typeof authHeader !== 'string') {
    return res.status(401).json({ error: 'Missing auth' });
  }

  let token: AuthToken;
  try {
    token = JSON.parse(Buffer.from(authHeader, 'base64').toString());
  } catch {
    return res.status(401).json({ error: 'Invalid auth format' });
  }

  if (!verifyServiceAuth(token)) {
    return res.status(403).json({ error: 'Auth failed' });
  }

  const { timestamp, level, message, context } = req.body;
  if (!timestamp || !level || !message) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  store.append({
    timestamp,
    service: token.serviceId,
    level,
    message,
    context: context || undefined
  });

  res.status(201).json({ status: 'ingested' });
});

app.get('/api/v1/view', (req: Request, res: Response) => {
  const service = req.query.service as string | undefined;
  const level = req.query.level as string | undefined;
  const entries = store.query(service, level);
  const html = buildLogWidget(entries);
  res.setHeader('Content-Type', 'text/html');
  res.send(html);
});

app.listen(3000, () => console.log('Log agent on :3000'));

export { app, verifyServiceAuth, sanitizeForDisplay, buildLogWidget };
